                summary: '服务器之前看到的是前面网络边缘节点的地址而不是你的地址，经过同一个边缘节点的人会共用一套登录限流额度。',
                limits: '登录、邮箱验证码、设备配对和 Google 登录的限流现在按每位访问者的地址计算，别人触发限流不会再连累你。',
