                prompt: '现在第一次被拒就会停掉全部后台同步，并弹出「登录已失效」，点「重新登录」登录后回到原来的页面。',
                retries: '后台保存与刷新失败时改为指数退避，几次之后就停，不再不间断重试；改动保留在本设备，之后再发送。',
