                listed: '这类 shell 现在会一直留在列表里，标为「临时」，直到你关掉它；闲置 20 分钟也不再被悄悄关掉。daemon 停止或机器重启时它仍会结束。',
                install: '终端页和新建终端对话框会提示这台机器没有 tmux，并给出安装命令（brew、apt，无 sudo 可用 conda）。装好后约 30 秒内新开的终端就会用上 tmux，无需重启 daemon。需要更新 CLI。',
