                release: '以前每个 Codex 会话都保活一个 codex app-server 直到会话结束，哪怕几天没人说话。这个进程一直打开着 Codex 的数据库，Codex App 以及需要独占 ~/.codex 的修复工具会被一个你看不见的进程挡住。在那台机器上设置 HAPPY_CODEX_IDLE_RELEASE_MS 可以改延时，设为 0 则保留旧行为。',
