                gfm: '新支持的还有：嵌套列表、任务清单、删除线、裸链接、引用式链接和脚注。转义的竖线和缺格的数据行不会再把表格的列错开，foo_bar_baz 这类标识符也不会再有一半变成斜体。agent 正文里引用的图片以标签形式显示，不会去远程服务器加载。',
                attachments: '以前发文件会多出一条塞满机器标记的重复消息，文件本身还显示成上面一行工具调用。重复消息没有了，附件跟着你的消息一起显示，图片直接出缩略图、点开看大图。',
