                hang: '重新加载之前，应用会让浏览器刷新它缓存的站点副本。这一步此前是无限期等待的，一旦卡住，重新加载就永远不会发生。现在给它加了时限，无论结果如何都会继续重新加载——反正加载本身就会取到新版本。',
