                command: '「在目录里开终端」现在多了启动命令一栏：设置里的默认值、你以前从这里启动过的命令，以及一个明确的「不执行命令」（只开一个 shell）。手打的命令会被记成一个 chip，下次一键切换。',
                recents: '目录 chip 里现在还会带上你最近在那台机器上开过的目录——和新建对话记住的是同一份，从这里开终端也会写进去。收藏过的目录仍然排在前面，也只有它们带删除按钮；最近用过的会自己淘汰。',
