                dot: '终端里的 agent 停下来时（跑完一轮，或者 claude 退回 shell），那一行会出现同样的红点，点进去就消失。它记在这台设备上，刷新页面也还在。',
                rules: '有两种情况刻意不标：你此刻正开着的那个终端，以及刷新后看到的第一个状态（否则一打开页面所有空闲终端都会亮红）。等你输入的终端仍然是青色标记，并且优先级高于红点。',
