                width: '在字体还没下载完的时候新建的终端，列数会是错的；而且这不是刷新一下就好的事：宽度会被写进 tmux 会话和 agent 的第一屏输出，终端历史又永远不会重排。现在它会等自己字体栈里的每一个网络字体。',
