                drawer: '子代理那一行只说三件事：它是谁、正在做什么、跑了多久。点一下打开侧边面板（手机上是整屏），里面有折叠起来的任务说明、完整的执行过程，以及它最后交回来的报告。',
                stop: '点「终止」现在会一次性停干净。以前对话底部的活动指示在「已由你停止」出现之后还会继续转——子代理卡片仍然声称自己在跑，后台子代理更是永远停不下来。被打断的子代理现在如实显示为「已停止」，而不是像以前那样悄悄翻成「已完成」。',
