                model: '换模型现在从你发出的下一条消息起必定生效（打断注入当前回合的那条仍由当前模型回答）。此前只要这次切换紧跟在上一次模式变更之后就会被丢掉——跑着的 Claude Code 进程仍用旧模型，而界面上没有任何东西提示不一致。切换还改成对运行中的会话原地生效，不再重启进程、重载对话记录。选择器会显示当前真正在跑的模型。',
